  ('standing', 'rnc-from-standing-back', '리어 네이키드 초크 (스탠딩)', 'Rear Naked Choke from Standing Back Control', array['스탠딩 RNC']::text[], array['뒤에서 한 팔을 상대 목 앞으로 넣는다','그 손을 반대 팔 이두에 걸고 반대 손은 뒤통수','가슴을 등에 붙이고 체중으로 상대를 뒤로 끌어내린다','팔꿈치를 모아 조인다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 56),
  ('standing', 'kimura-from-standing', '기무라 (스탠딩)', 'Kimura from Standing', array['스탠딩 기무라']::text[], array['상대 손목을 잡고 반대 팔로 윗팔을 감아 내 손목을 잡는다','팔꿈치를 몸에 붙이고 상대 옆으로 선다','팔을 등 뒤로 돌리며 상대를 바닥으로 끌어내린다','사이드나 남북에서 마무리']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph standing-position/top (기 시도 1)', 57),
  ('closed-guard', 'closed-guard-basics', '클로즈드 가드 (자세 · 포스처 깨기)', 'Closed Guard (Basics & Breaking Posture)', array['풀 가드','클로즈 가드','가드 유지']::text[], array['양 다리를 상대 허리 뒤에서 교차해 발목을 잠근다','무릎을 조이고 다리로 당겨 상대 가슴을 내 쪽으로 무너뜨린다(포스처 깨기)','한 손은 목 뒤, 한 손은 소매나 깃을 잡는다 — 목 뒤 그립은 손목을 걸어 한쪽으로 모은다','상대 팔이 내 가슴을 밀면 안쪽에서 바깥으로 쳐내 바닥에 짚게 만든다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJ Commons §2.1', 1),
  ('closed-guard', 'scissor-sweep', '시저 스윕', 'Scissor Sweep', array['가위 스윕']::text[], array['깃과 소매(또는 팔꿈치)를 잡고 상대를 앞으로 당긴다','가드를 열고 엉덩이를 살짝 빼서 한 무릎을 상대 배 앞에 가로로 댄다(니 쉴드)','반대 다리는 바닥 가까이 내려 상대 무릎 바깥에 건다','위 다리는 밀고 아래 다리는 당기며(가위) 소매를 당겨 넘기고 마운트로 올라간다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJ Commons §2.2 · BJJGraph closed-guard/bottom 1위', 2),
  ('closed-guard', 'hip-bump-sweep', '힙 범프 스윕', 'Hip Bump Sweep', array['시트업 스윕','힙범프']::text[], array['상대가 상체를 세우고 내 가슴을 누를 때 — 가드를 풀고 한 손으로 뒤 바닥을 짚으며 앉아 일어난다','반대 팔을 상대 어깨 위로 넘겨 삼두(팔 뒤)를 감싼다','엉덩이를 높이 들어 상대 어깨를 옆으로 친다','넘어가면 다리를 180도 돌려 마운트. 상대가 손을 짚으면 기무라, 앞으로 밀면 길로틴으로 잇는다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJ Commons §2.2 (힙범프 → 기무라 → 길로틴 체인)', 3),
  ('closed-guard', 'flower-sweep', '플라워 스윕 (펜듈럼)', 'Flower / Pendulum Sweep', array['펜듈럼 스윕','플라워']::text[], array['한쪽 소매(또는 손목)와 같은 쪽 바지 무릎 안쪽을 잡는다','가드를 열고 소매 쪽 다리를 상대 겨드랑이 쪽으로 높게 올린다','반대 다리는 바닥 가까이 크게 돌린다(진자처럼) — 반대 팔로 상대 다리 아래를 안으면 더 강하다','올린 다리로 겨드랑이를 치며 돌려 넘기고 팔을 잡은 채 마운트로']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJ Commons §2.2 · BJJGraph', 4),
  ('closed-guard', 'cross-collar-choke-guard', '크로스 칼라 초크 (가드)', 'Cross Collar Choke from Closed Guard', array['크로스 초크','십자 조르기','칼라 초크']::text[], array['한 손을 상대 깃 깊숙이 넣는다(엄지 안쪽, 손바닥 위로)','반대 손은 첫 손 위로 교차해 반대 깃을 잡는다','상대를 다리로 당기며 팔꿈치를 아래로 떨어뜨린다','손목을 비틀어 양쪽 목 옆을 조인다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph closed-guard/bottom (기 4위)', 5),
  ('closed-guard', 'closed-guard-armbar', '클로즈드 가드 암바', 'Armbar from Closed Guard', array['암바','주짓수 암바']::text[], array['상대 한 팔을 가슴에 붙여 손목을 잡고, 반대 손은 그 팔의 삼두를 잡아 중앙으로 당긴다','같은 쪽 발을 상대 골반에 밟고 엉덩이를 돌려 몸을 상대와 직각으로 만든다','반대 다리를 상대 등 위로 올려 머리를 누르고 자세를 낮춘다','다리를 모아 무릎을 조이고 엉덩이를 들어 팔꿈치를 편다(엄지는 위로)']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJ Commons §2.3', 6),
  ('closed-guard', 'triangle-choke', '트라이앵글 초크', 'Triangle Choke', array['트라이앵글','삼각 조르기']::text[], array['상대 한 손목을 잡아 한 팔은 안쪽, 한 팔은 바깥쪽이 되게 만든다','가드를 열고 안쪽 팔 쪽 다리를 상대 목 뒤로 올리고 반대 다리는 겨드랑이 아래로','그 발목을 반대 무릎 뒤에 걸어 삼각형을 만들고, 두 손으로 머리를 당겨 자세를 낮춘다','목 위 다리 반대쪽으로 몸을 틀어 각도를 만들고 안쪽 팔을 얼굴 반대로 넘긴 뒤 다리를 조인다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJ Commons §2.3 (각도 규칙) · BJJGraph', 7),
  ('closed-guard', 'kimura-guard', '기무라 (가드)', 'Kimura from Closed Guard', array['키무라','기무라 락']::text[], array['상대 손목을 잡고 반대 팔로 윗팔을 감아 내 손목을 잡는다(8자 그립)','엉덩이를 옆으로 빼서 상대와 직각에 가깝게 눕는다','팔꿈치를 상대 어깨에 눌러 붙인 채 다리로 상대 몸을 묶는다','상대 손이 등 뒤 머리 쪽으로 가게 돌려 탭을 받는다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJ Commons §2.2 · §11.3', 8),
  ('closed-guard', 'omoplata', '오모플라타', 'Omoplata', array['오모플라따']::text[], array['상대 한 팔의 삼두를 잡고 머리를 당겨 포스처를 깬다','가드를 열고 그 팔 쪽으로 엉덩이를 빼며 같은 쪽 다리를 상대 팔 위 · 등 뒤로 넘긴다','발목을 상대 목에 걸고 반대 다리를 모아 어깨를 감싼다','앉아 올라오며 상대 허리를 잡아 못 일어나게 하고 엉덩이를 앞으로 밀어 어깨를 꺾는다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJ Commons §2.3 (골반 눕히기 디테일)', 9),
  ('closed-guard', 'arm-drag-guard', '암 드래그 → 백 테이크 (가드)', 'Arm Drag to Back from Closed Guard', array['암드랙','팔 끌어 백 잡기']::text[], array['상대 한 손목을 잡고 반대 손으로 삼두를 잡는다(투 온 원)','다리로 상대를 당겨 가슴을 붙이고 팔을 내 몸 반대쪽으로 끌어 넘긴다','가드를 풀고 옆으로 일어나며 반대 팔로 상대 등 뒤 겨드랑이를 잡는다','훅을 넣고 시트벨트를 잡아 백 컨트롤로']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJ Commons §2.2 · §8.1', 10),
  ('closed-guard', 'guillotine-guard', '길로틴 초크 (가드)', 'Guillotine from Closed Guard', array['가드 길로틴']::text[], array['상대 머리가 내 가슴 쪽으로 숙여질 때(힙 범프를 막으려 밀 때 등) 한 팔을 목 앞으로 감는다','감은 손을 반대 손으로 잡아 그립을 만들고 팔꿈치를 몸에 붙인다','상대 머리가 있는 쪽으로 몸을 틀고 다리를 감아 못 빠지게 한다','뒤로 젖히지 말고 가슴을 펴며 체중으로 목을 조인다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJ Commons §9.4 · §11.6', 11),
  ('closed-guard', 'posture-recovery', '클로즈드 가드 안 자세 되찾기', 'Posture Recovery inside Closed Guard', array['포스처 리커버리']::text[], array['당겨 무너지면 먼저 머리를 들고 시선을 위로','손을 상대 가슴이나 갈비에 짚어 팔꿈치를 편다','엉덩이를 뒤로 빼며 허리를 세운다','무릎을 벌려 베이스를 만든다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph closed-guard/top (기 시도 27)', 12),
  ('closed-guard', 'stack-defense', '스택 당했을 때 방어 (가드)', 'Stack Defense in Closed Guard', array['스택 디펜스']::text[], array['상대가 내 다리를 머리 쪽으로 누르면 발을 상대 골반에 대어 밀어낸다','턱을 당기고 목이 꺾이지 않게 한다','엉덩이를 옆으로 빼서 압력을 피한다','가드를 다시 잠그거나 오픈 가드로']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph closed-guard/bottom (기 시도 19)', 13),
  ('closed-guard', 'omoplata-sweep', '오모플라타 스윕', 'Omoplata Sweep', array['오모플라타로 넘기기']::text[], array['오모플라타 자세에서 상대 허리를 잡아 못 구르게 한다','상대가 앞으로 못 넘어가면 반대쪽으로 몸을 돌려 상대를 옆으로 민다','다리로 상대 어깨를 계속 누른다','넘어가면 위로 올라와 마운트나 사이드']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph closed-guard/bottom (기 시도 23)', 14),
  ('closed-guard', 'overhook-sweep', '오버훅 스윕', 'Overhook Sweep', array['위즐 스윕']::text[], array['상대 한 팔을 위에서 감아(오버훅) 내 몸에 붙인다','반대 손으로 상대 반대 손목이나 소매를 잡는다','오버훅 쪽으로 엉덩이를 빼며 다리로 상대 다리를 들어 올린다','넘기고 마운트']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph closed-guard/bottom (기 시도 15)', 15),
  ('closed-guard', 'kimura-sweep', '기무라 스윕', 'Kimura Sweep', array['기무라로 넘기기']::text[], array['기무라 그립을 잡고 상대가 손을 바닥에 짚어 버티게 만든다','그립을 유지한 채 엉덩이를 옆으로 빼고 다리를 상대 등 위로 넘긴다','상대 팔을 당기며 그쪽으로 몸을 돌려 넘긴다','위로 올라와 기무라를 계속 공격']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph closed-guard/bottom (기 시도 13)', 16),
  ('closed-guard', '100-percent-sweep', '100% 스윕 (지하에서 안아 넘기기)', '100% Sweep', array['백퍼센트 스윕']::text[], array['클로즈드 가드에서 상대가 서면 한 손은 상대 발목(바지), 반대 손은 뒤 바닥을 짚고 앉는다','가드를 풀고 상대 다리 하나를 양팔로 안는다','어깨로 상대 무릎을 밀며 앞으로 밀어 눕힌다','다리를 놓지 않고 패스 자세로']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph closed-guard/bottom (기 시도 10)', 17),
  ('closed-guard', 'arm-trap-sweep', '암 트랩 스윕', 'Arm Trap Sweep', array['팔 가두고 넘기기']::text[], array['상대가 내 목 앞으로 팔을 밀어 넣으면 그 팔꿈치를 반대쪽으로 민다','그 팔을 내 머리와 팔로 감싸 가둔다(헤드 앤 암)','가둔 쪽으로 엉덩이를 돌려 균형을 깬다','넘기고 위로']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 18),
  ('closed-guard', 'clamp-sweep', '클램프 스윕', 'Clamp Sweep', array['가슴 붙여 넘기기']::text[], array['암 드래그가 안 넘어가면 반대 팔로 상대 겨드랑이를 감아 가슴을 붙인다','한쪽 엉덩이로 돌아 상대 팔이 못 돌아오게 배로 막는다','무릎을 상대 무릎 쪽으로 차 내며 옆으로 굴린다','위로 올라와 키락']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 19),
  ('closed-guard', 'closed-guard-to-overhook-guard', '클로즈드 가드 → 오버훅 가드', 'Closed Guard to Overhook Guard', array['오버훅 가드 진입']::text[], array['상대 한 팔을 위에서 감아 오버훅을 잡는다','오버훅 쪽으로 몸을 틀고 반대 손으로 상대 손목을 컨트롤','상대 팔을 내 옆구리에 가둔다','스윕 · 오모플라타 · 트라이앵글로 잇는다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph closed-guard/bottom (기 시도 3)', 20),
  ('closed-guard', 'switch-to-triangle', '트라이앵글로 전환', 'Switch to Triangle', array['트라이앵글 스위치']::text[], array['암바나 오모플라타를 막으면 상대 한 팔이 안쪽에 남는다','그 팔 쪽 다리를 상대 목 뒤로 올린다','반대 다리로 발목을 걸어 삼각형','머리를 당기고 각도를 틀어 조인다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph closed-guard/bottom (기 시도 2)', 21),
  ('closed-guard', 'wrist-lock-closed-guard', '리스트락 (가드)', 'Wrist Lock from Closed Guard', array['손목 꺾기']::text[], array['상대 손이 내 가슴이나 깃을 잡을 때 그 손등을 위에서 덮는다','손목이 굽혀진 채 팔꿈치가 못 움직이게 반대 손으로 팔을 고정','손등을 팔 안쪽으로 밀어 손목을 접는다','천천히 눌러 탭을 받는다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 22),
  ('closed-guard', 'loop-choke-closed-guard', '루프 초크 (가드)', 'Loop Choke from Closed Guard', array['루프초크']::text[], array['상대 깃을 한 손으로 잡고 상대 머리를 숙이게 한다','잡은 팔 아래로 상대 머리를 넣듯 팔꿈치를 돌려 깃으로 목을 감는다','반대 팔을 상대 등 뒤로 넘겨 그립을 받친다','몸을 돌리며 조인다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 23),
  ('closed-guard', 'muscle-sweep', '머슬 스윕', 'Muscle Sweep', array['힘 스윕']::text[], array['상대가 서려 할 때 양 발목(바지)을 잡는다','다리로 상대 허리를 조이며 뒤로 눕는다','발목을 당기고 무릎으로 상대 배를 밀어 뒤로 앉힌다','위로 올라와 마운트나 패스 자세']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph closed-guard/bottom (기 시도 1)', 24),
  ('closed-guard', 'ezekiel-choke-closed-guard', '에제키엘 초크 (가드 안에서)', 'Ezekiel Choke from inside Closed Guard', array['가드 안 에제키엘']::text[], array['상대 클로즈드 가드 안에서 한 팔을 상대 머리 아래로 넣는다','반대 손으로 그 팔 소매 안쪽을 잡는다','자유로운 손날을 상대 목 앞으로 넣는다','가슴을 눌러 자세를 낮추며 조인다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 25),
  ('closed-guard', 'can-opener', '캔 오프너 (가드 열기)', 'Can Opener', array['캔오프너']::text[], array['클로즈드 가드 안에서 양손을 상대 뒤통수에 깍지 낀다','허리를 세우며 상대 머리를 가슴 쪽으로 당긴다','상대가 목이 불편해 가드를 풀면 바로 열어 패스','(목 크랭크라 체육관 규칙 확인)']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 26),
  ('closed-guard', 'overhook-control-sweep', '오버훅 컨트롤 스윕', 'Overhook Control Sweep', array['오버훅에서 넘기기']::text[], array['오버훅으로 상대 팔을 가두고 반대 손은 상대 손목','오버훅 반대쪽으로 엉덩이를 빼며 무릎을 상대 배에 댄다','다리로 밀고 팔을 당겨 넘긴다','마운트로']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph overhook-control/bottom (기 시도 13)', 27),
  ('closed-guard', 'overhook-to-half-guard', '오버훅 → 하프가드', 'Overhook to Half Guard', array['오버훅 하프 전환']::text[], array['오버훅을 유지한 채 가드를 연다','한쪽 다리로 상대 다리 하나를 감는다','오버훅 쪽으로 옆으로 돌아 눕는다','하프가드에서 언더훅 싸움']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph overhook-control/bottom (기 시도 8)', 28),
  ('closed-guard', 'kimura-from-overhook-control', '기무라 (오버훅 컨트롤 위에서)', 'Kimura from Overhook Control (Top)', array['오버훅 기무라']::text[], array['상대가 내 팔을 오버훅으로 잡으면 그 손목을 잡는다','반대 팔을 상대 팔 아래로 넣어 내 손목을 잡는다','상대 어깨를 바닥에 누르며 몸을 낮춘다','팔을 등 뒤로 돌린다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph overhook-control/top (기 시도 16)', 29),
  ('closed-guard', 'darce-from-overhook-control', '다스 (오버훅 컨트롤 위에서)', 'Darce from Overhook Control', array['오버훅 다스']::text[], array['상대가 오버훅을 잡고 몸을 틀면 그 팔 아래로 내 팔을 넣는다','목 반대편까지 깊게 꿰어 이두를 잡는다','상대 머리를 누르며 몸을 낮춘다','가슴으로 조인다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 30),
  ('closed-guard', 'overhook-pass-to-side-control', '오버훅 풀고 패스', 'Overhook Pass to Side Control', array['오버훅 패스']::text[], array['오버훅 잡힌 팔꿈치를 몸 쪽으로 당겨 빼낸다','빠지면 바로 상대 무릎을 눌러 가드를 연다','니슬라이스로 다리를 지난다','사이드 컨트롤']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph overhook-control/top (기 시도 15)', 31),
  ('closed-guard', 'whizzer', '위저 (오버훅으로 막기)', 'Whizzer', array['위저','오버훅 카운터']::text[], array['상대가 언더훅을 잡으면 그 팔을 위에서 감는다(위저)','팔을 조여 상대 어깨를 바닥 쪽으로 누른다','엉덩이를 뒤로 빼 상대가 못 일어나게 한다','상대 등 뒤로 돌아 백이나 패스']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph overhook-control/top (기 시도 3)', 32),
  ('closed-guard', 'break-overhook-guard', '오버훅 가드 풀기', 'Break Overhook Guard', array['오버훅 가드 브레이크']::text[], array['오버훅 잡힌 팔꿈치를 몸에 붙이고 허리를 세운다','반대 손으로 상대 골반을 눌러 거리를 만든다','팔꿈치를 아래로 돌려 오버훅을 빼낸다','클로즈드 가드 안 자세로 돌아간다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph overhook-guard/top (기 시도 30)', 33),
  ('closed-guard', 'overhook-guard-sweep', '오버훅 가드 스윕', 'Overhook Guard Sweep', array['오버훅 가드에서 넘기기']::text[], array['오버훅을 깊게 감고 반대 손은 상대 반대 소매','오버훅 쪽으로 엉덩이를 빼며 다리로 상대 다리 들기','소매를 당겨 넘긴다','마운트']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph overhook-guard/bottom (기 시도 11)', 34),
  ('closed-guard', 'omoplata-from-overhook-guard', '오모플라타 (오버훅 가드)', 'Omoplata from Overhook Guard', array['오버훅 오모플라타']::text[], array['오버훅을 잡은 채 가드를 열고 엉덩이를 뺀다','오버훅 쪽 다리를 상대 팔 위 · 등 뒤로 넘긴다','발목을 목에 걸고 다리를 모은다','앉아 올라오며 어깨를 꺾는다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 35),
  ('closed-guard', 'closed-guard-to-triangle', '클로즈드 가드 → 트라이앵글 세팅', 'Closed Guard to Triangle Setup', array['트라이앵글 셋업']::text[], array['한 손목을 잡아 내 골반 쪽으로 밀어 상대 팔 하나를 바깥으로 뺀다','같은 쪽 발을 상대 골반에 대고 엉덩이를 들어 올린다','반대 다리를 상대 목 뒤로 넘긴다','발목을 걸어 트라이앵글 컨트롤']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph closed-guard/bottom (기 시도 14)', 36),
  ('open-guard', 'technical-stand-up', '테크니컬 스탠드업', 'Technical Stand-Up', array['테크니컬 겟업','기본 일어서기']::text[], array['앉은 자세에서 한 손은 뒤 바닥을 짚고 반대 손은 앞을 막는다(프레임)','짚은 손 반대 발을 세우고 엉덩이를 들어 올린다','세운 발과 손 사이로 반대 다리를 빼서 뒤로 보낸다','무릎을 펴고 일어서며 앞 손은 계속 상대를 막는다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph open-guard/bottom · 기초', 1),
  ('open-guard', 'shrimp-hip-escape', '쉬림프 (힙 이스케이프)', 'Shrimp / Hip Escape', array['새우','힙 이스케이프']::text[], array['등을 대고 누워 한 발로 바닥을 민다','같은 쪽 어깨로 돌아 누우며 엉덩이를 뒤로 뺀다','팔꿈치와 손으로 상대를 밀어(프레임) 생긴 공간을 유지한다','무릎을 상대와 나 사이로 넣어 가드를 되찾는다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJ Commons §1.4 · 기초', 2),
  ('open-guard', 'tripod-sweep', '트라이포드 스윕', 'Tripod Sweep', array['삼각대 스윕']::text[], array['상대 한쪽 소매와 같은 쪽 발목을 잡는다','발목 잡은 쪽 발을 상대 골반에 대고 민다','반대 발로 상대 반대 다리 뒤(오금)를 걸어 당긴다','밀고 당기며 뒤로 눕히고 발목을 놓지 않고 일어나 패스 자세로']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph open-guard/bottom', 3),
  ('open-guard', 'sickle-sweep', '시클 스윕', 'Sickle Sweep', array['낫 스윕']::text[], array['트라이포드와 같은 그립(소매 · 발목)에서 시작한다','골반에 댄 발을 떼어 상대 반대 발목 바깥을 낫처럼 건다','반대 발은 상대 무릎이나 골반을 밀어 낸다','걸고 밀며 상대를 옆으로 넘기고 일어난다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph open-guard/bottom', 4),
  ('open-guard', 'grip-break', '그립 끊기 (오픈 가드)', 'Grip Break in Open Guard', array['그립 브레이크']::text[], array['상대가 내 바지나 발목을 잡으면 발을 돌려 그립 약한 방향으로 뺀다','깃을 잡히면 손목을 돌리고 몸을 틀어 뗀다','끊는 동시에 내 그립을 먼저 잡는다','발을 상대 골반 · 이두에 대어 거리를 회복한다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph open-guard/bottom (기 시도 26)', 5),
  ('open-guard', 'feet-on-hips-guard', '발 골반 가드 (피트 온 힙스)', 'Feet on Hips Guard', array['피트온힙스','발 골반']::text[], array['누워서 양 발바닥을 상대 골반 앞에 댄다','양 소매나 깃을 잡아 상대 팔을 컨트롤한다','발로 밀고 손으로 당겨 거리를 지킨다','상대가 서면 데라히바나 스파이더로 바꾼다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 6),
  ('open-guard', 'push-sweep-from-feet-on-hips', '푸시 스윕', 'Push Sweep from Feet on Hips', array['밀어 넘기기']::text[], array['발 골반 가드에서 양 소매를 당긴다','상대가 뒤로 버티는 순간 양 발로 골반을 강하게 민다','상대가 뒤로 앉으면 발목을 잡고 일어난다','패스 자세로']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph feet-on-hips-guard/bottom (기 시도 9)', 7),
  ('open-guard', 'balloon-sweep', '벌룬 스윕', 'Balloon Sweep', array['풍선 스윕']::text[], array['양 소매를 잡고 양 발을 상대 골반에 댄다','상대를 당기며 뒤로 누워 발로 상대를 머리 위로 띄운다','띄운 상태에서 몸을 돌려 상대를 옆으로 넘긴다','굴러 올라와 마운트']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph feet-on-hips-guard/bottom (기 시도 7)', 8),
  ('open-guard', 'feet-on-hips-tripod-sweep', '트라이포드 스윕 (발 골반에서)', 'Tripod Sweep from Feet on Hips', array['발 골반 트라이포드']::text[], array['한 발은 골반에 두고 같은 쪽 손으로 상대 발목을 잡는다','반대 발로 상대 반대 오금을 건다','밀고 걸며 뒤로 눕힌다','발목을 놓지 않고 일어난다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph feet-on-hips-guard/bottom (기 시도 4)', 9),
  ('open-guard', 'feet-on-hips-sickle-sweep', '시클 스윕 (발 골반에서)', 'Sickle Sweep from Feet on Hips', array['발 골반 시클']::text[], array['소매와 반대 발목을 잡는다','골반에 댄 발을 떼어 상대 발목 바깥을 낫처럼 건다','반대 발로 골반을 민다','옆으로 넘기고 일어난다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph feet-on-hips-guard/bottom (기 시도 4)', 10),
  ('open-guard', 'feet-on-hips-to-de-la-riva', '발 골반 → 데라히바', 'Feet on Hips to De La Riva', array['데라히바 진입']::text[], array['상대가 한 발을 앞으로 내면 그 발목을 잡는다','같은 쪽 다리를 상대 다리 바깥으로 감아 훅을 건다','반대 발은 골반에 남긴다','소매를 잡아 데라히바 완성']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph feet-on-hips-guard/bottom (기 시도 11)', 11),
  ('open-guard', 'collar-drag-from-open-guard', '칼라 드래그 (오픈 가드)', 'Collar Drag from Open Guard', array['앉아서 깃 끌기']::text[], array['앉은 가드에서 상대 깃을 깊게 잡는다','뒤로 앉으며 깃을 바닥 쪽으로 강하게 끌어 당긴다','상대가 앞으로 쏠리면 옆으로 빠져 뒤로 돈다','프론트 헤드락이나 백']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph open-guard/bottom (기 시도 11)', 12),
  ('open-guard', 'recovery-from-failed-sweep', '스윕 실패 후 복귀', 'Recovery from Failed Sweep', array['리커버리']::text[], array['스윕이 막히면 바로 그립을 놓지 않고 몸을 상대 쪽으로 돌린다','손으로 바닥을 짚고 테크니컬 스탠드업으로 일어난다','또는 앉아서 발을 상대 골반에 대어 거리 회복','다시 가드 그립부터']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph open-guard/bottom (기 시도 5)', 13),
  ('open-guard', 'open-guard-to-deep-half', '오픈 가드 → 딥 하프', 'Open Guard to Deep Half', array['딥 하프 진입']::text[], array['상대가 무릎 서서 다가오면 한 다리를 상대 다리 사이로 넣는다','상대 허벅지 아래로 깊게 들어가며 옆으로 돈다','상대 허벅지를 안고 머리를 숨긴다','딥 하프 완성']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph open-guard/bottom (기 시도 3)', 14),
  ('open-guard', 'scissor-sweep-from-open-guard', '시저 스윕 (오픈 가드)', 'Scissor Sweep from Open Guard', array['오픈 가드 시저']::text[], array['깃과 소매를 잡고 한 무릎을 상대 배 앞에 가로로 댄다','반대 다리는 바닥 가까이 상대 무릎 바깥','상대를 당기며 가위처럼 돌린다','마운트']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph open-guard/bottom (기 시도 3)', 15),
  ('open-guard', 'triangle-choke-from-open-guard', '트라이앵글 (오픈 가드)', 'Triangle Choke from Open Guard', array['오픈 가드 트라이앵글']::text[], array['상대 한 팔을 소매로 밀어 바깥에 두고 반대 팔은 안쪽','안쪽 팔 쪽 다리를 상대 목 뒤로 올린다','반대 다리로 발목을 걸어 삼각형','각도를 틀고 머리를 당겨 조인다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph open-guard/bottom (기 시도 4)', 16),
  ('open-guard', 'belly-down-armbar-open-guard', '벨리 다운 암바 (오픈 가드)', 'Belly Down Armbar from Open Guard', array['엎드린 암바']::text[], array['상대 팔을 잡고 몸을 상대 옆으로 돌린다','다리를 상대 머리 위로 넘기며 엎드린다','무릎을 모아 상대 팔을 가슴에 붙인다','엉덩이를 들어 팔꿈치를 편다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 17),
  ('open-guard', 'foot-grab-sweep', '발 잡아 넘기기 (시팅 가드)', 'Foot Grab Sweep', array['앵클 그랩 스윕']::text[], array['앉은 가드에서 상대 한쪽 발목을 잡는다','반대 손은 상대 깃이나 소매','발목을 당기며 깃을 밀어 뒤로 눕힌다','발목을 놓지 않고 일어나 패스']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph seated-guard/bottom (기 시도 11)', 18),
  ('open-guard', 'ankle-pick-sweep', '앵클 픽 스윕', 'Ankle Pick Sweep', array['앉아서 발목 잡기']::text[], array['앉은 가드에서 상대 발목 바깥을 한 손으로 잡는다','반대 손으로 상대 무릎 안쪽을 민다','어깨를 상대 다리에 붙이며 일어난다','넘어가면 헤드쿼터 자세']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph seated-guard/bottom (기 시도 11)', 19),
  ('open-guard', 'lumberjack-sweep', '럼버잭 스윕', 'Lumberjack Sweep', array['나무꾼 스윕']::text[], array['상대가 서 있을 때 양 발목(뒤꿈치)을 양손으로 잡는다','발로 상대 무릎이나 골반을 밀며 발목을 당긴다','상대가 뒤로 넘어진다','발목을 놓지 않고 일어나 패스']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph seated-guard/bottom (기 시도 7)', 20),
  ('open-guard', 'shin-to-shin-guard', '신 투 신 가드', 'Shin-to-Shin Guard', array['정강이 가드']::text[], array['앉은 자세에서 내 정강이를 상대 정강이 앞에 가로로 댄다','같은 쪽 손으로 상대 발목이나 바지를 잡는다','반대 손으로 깃이나 소매를 잡아 상대를 당긴다','싱글 레그 X · 스윕으로 잇는다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 21),
  ('open-guard', 'shin-to-shin-sweep', '신 투 신 스윕', 'Shin-to-Shin Sweep', array['정강이 스윕']::text[], array['신 투 신에서 상대 발목을 잡고 깃을 당긴다','정강이로 상대 다리를 들어 올리며 옆으로 눕는다','상대가 뒤로 앉으면 발목을 들고 위로 올라간다','마운트나 패스 자세']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph shin-to-shin-guard/bottom (기 시도 15)', 22),
  ('open-guard', 'shin-to-shin-to-single-leg-x', '신 투 신 → 싱글 레그 X', 'Shin-to-Shin to Single Leg X', array['SLX 진입']::text[], array['신 투 신에서 발목을 잡은 채 뒤로 눕는다','정강이 댄 다리를 상대 다리 안쪽으로 돌려 발을 골반에 건다','반대 다리로 상대 허벅지 안쪽을 감는다','발목을 가슴에 안고 싱글 레그 X']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph shin-to-shin-guard/bottom (기 시도 19)', 23),
  ('open-guard', 'technical-stand-up-to-single-leg', '테크니컬 스탠드업 → 싱글 레그', 'Technical Stand-Up to Single Leg', array['일어나며 싱글렉']::text[], array['앉은 가드에서 상대 발목을 잡고 테크니컬 스탠드업','일어나며 상대 다리를 양팔로 안는다','머리를 상대 가슴에 붙인다','싱글 레그로 넘긴다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph turtle/bottom (기 시도 14)', 24),
  ('butterfly-guard', 'butterfly-guard', '버터플라이 가드', 'Butterfly Guard', array['버터플라이','나비 가드']::text[], array['앉은 자세에서 양 발을 상대 허벅지 안쪽에 훅처럼 넣는다','무릎은 바깥으로 벌리고 발등으로 들어 올린다(무릎을 모으지 않는다)','상체를 세우고 언더훅이나 깃을 잡아 가슴을 붙인다','엉덩이를 상대 가까이 당겨 거리를 없애고 스윕을 노린다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJ Commons §5.1', 1),
  ('butterfly-guard', 'butterfly-sweep', '버터플라이 스윕', 'Butterfly Sweep', array['훅 스윕']::text[], array['버터플라이 가드에서 한쪽 언더훅을 잡고 반대 손은 소매나 손목을 잡는다','언더훅 쪽으로 몸을 기울이며 상대 체중을 받는다','같은 쪽 훅 발로 상대 다리를 들어 올리며 옆으로 눕는다','굴러 넘어가 위로 올라온다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph butterfly-guard/bottom 1위', 2),
  ('butterfly-guard', 'elevator-sweep', '엘리베이터 스윕', 'Elevator Sweep', array['엘레베이터 스윕']::text[], array['상대가 무릎 서서 들어올 때 한 발을 상대 허벅지 안쪽에 훅으로 넣는다','반대 다리는 상대 다리 바깥을 감거나 바닥에 둔다','상대 팔이나 깃을 당기며 훅 발로 다리를 위로 들어 올린다','들린 쪽으로 넘기고 위로 올라온다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph butterfly-guard/bottom 2위', 3),
  ('butterfly-guard', 'arm-drag-to-back-butterfly', '암 드래그 → 백 (버터플라이)', 'Arm Drag to Back from Butterfly', array['버터플라이 암드랙']::text[], array['버터플라이 가드에서 상대 손목과 삼두를 잡는다','팔을 내 옆으로 끌며 훅으로 상대를 띄운다','상대 옆으로 빠져 등 뒤로 돈다','훅을 넣고 백']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 4),
  ('butterfly-guard', 'hook-sweep', '훅 스윕 (한쪽 훅)', 'Hook Sweep', array['원 훅 스윕']::text[], array['한쪽 훅만 상대 허벅지 안쪽에 두고 반대 다리는 뒤로 뺀다','언더훅이나 깃을 잡고 상대를 당긴다','훅으로 다리를 들며 옆으로 눕는다','굴러 사이드 탑']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph butterfly-guard/bottom (기 시도 14)', 5),
  ('butterfly-guard', 'butterfly-guard-to-x-guard', '버터플라이 → X 가드', 'Butterfly Guard to X-Guard', array['X가드 진입']::text[], array['상대가 서려 할 때 한쪽 훅 다리를 상대 다리 사이로 넣는다','머리를 상대 다리 아래로 숨기며 반대 다리를 상대 반대 다리에 건다','상대 한쪽 다리를 어깨에 얹는다','X 가드 완성']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph butterfly-guard/bottom (기 시도 11)', 6),
  ('butterfly-guard', 'butterfly-smash', '버터플라이 스매시 패스', 'Butterfly Smash Pass', array['버터플라이 스매시']::text[], array['버터플라이 위에서 상대 한쪽 훅 무릎을 바닥으로 누른다','가슴으로 상대를 눌러 눕힌다','상대 양 무릎을 한쪽으로 모아 체중으로 깔아뭉갠다','다리를 빼며 사이드로']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph butterfly-guard/top (기 시도 11)', 7),
  ('butterfly-guard', 'guillotine-from-butterfly', '길로틴 (버터플라이)', 'Guillotine from Butterfly Guard', array['버터플라이 길로틴']::text[], array['상대가 머리를 숙이고 들어오면 팔을 목 앞으로 감는다','손을 맞잡고 훅으로 상대를 당겨 붙인다','뒤로 누우며 다리로 상대를 감는다','가슴을 펴며 조인다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 8),
  ('butterfly-guard', 'underhook-sweep-butterfly', '언더훅 스윕 (버터플라이)', 'Underhook Sweep from Butterfly', array['버터플라이 언더훅 스윕']::text[], array['언더훅을 깊게 잡고 상대 가슴을 붙인다','언더훅 쪽으로 몸을 기울이며 같은 쪽 훅으로 다리를 든다','반대 손으로 상대 손목을 잡아 못 짚게 한다','넘기고 사이드 탑']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 9),
  ('butterfly-guard', 'kimura-from-butterfly', '기무라 (버터플라이)', 'Kimura from Butterfly Guard', array['버터플라이 기무라']::text[], array['상대가 손을 바닥에 짚으면 그 손목을 잡는다','반대 팔로 윗팔을 감아 내 손목을 잡는다','옆으로 누우며 훅으로 상대를 밀어 어깨를 바닥에 붙인다','팔을 등 뒤로 돌린다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 10),
  ('butterfly-guard', 'omoplata-from-butterfly', '오모플라타 (버터플라이)', 'Omoplata from Butterfly Guard', array['버터플라이 오모플라타']::text[], array['상대 팔이 내 다리 바깥에 걸릴 때 그 팔 삼두를 잡는다','엉덩이를 빼며 다리를 상대 팔 위 · 등 뒤로 넘긴다','발목을 목에 걸고 다리를 모은다','앉아 올라오며 어깨를 꺾는다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 11),
  ('butterfly-guard', 'butterfly-half-guard', '버터플라이 하프가드', 'Butterfly Half Guard', array['하프 버터플라이']::text[], array['하프가드에서 안쪽 다리를 상대 허벅지 안쪽 훅으로 바꾼다','바깥 다리는 상대 다리를 계속 감는다','언더훅을 잡고 상체를 세운다','훅으로 들어 스윕이나 백 테이크']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 12),
  ('butterfly-guard', 'butterfly-half-guard-sweep', '버터플라이 하프가드 스윕', 'Butterfly Half Guard Sweep', array['하프 버터플라이 스윕']::text[], array['언더훅을 잡고 훅 다리로 상대 다리를 든다','언더훅 쪽으로 몸을 기울인다','상대 체중이 뜨면 옆으로 굴린다','위로 올라와 사이드']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph butterfly-half-guard/bottom (기 시도 10)', 13),
  ('butterfly-guard', 'reguard-from-butterfly-half', '버터플라이 하프 → 가드 회복', 'Reguard from Butterfly Half Guard', array['훅으로 가드 되찾기']::text[], array['훅으로 상대를 밀어 거리를 만든다','감은 다리를 빼서 상대 허벅지 안쪽에 넣는다','양 훅이 들어가면 상체를 세운다','버터플라이 가드']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 14),
  ('butterfly-guard', 'knee-slice-from-butterfly-half', '니슬라이스 (버터플라이 하프)', 'Knee Slice from Butterfly Half', array['하프 버터플라이 니슬라이스']::text[], array['상대 훅 무릎을 바닥으로 누른다','언더훅이나 깃을 잡아 상체를 눌러 둔다','정강이를 상대 허벅지 위로 미끄러뜨린다','사이드로']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph butterfly-half-guard/top (기 시도 10)', 15),
