  ('butterfly-guard', 'half-butterfly-to-dogfight', '버터플라이 하프 → 도그파이트', 'Half Butterfly to Dogfight', array['도그파이트 진입']::text[], array['언더훅을 잡고 훅으로 상대를 띄운다','상체를 세우며 무릎으로 일어난다','상대 다리를 안고 네발 자세(도그파이트)','스윕이나 백 테이크로']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph half-butterfly/bottom (기 시도 9)', 17),
  ('butterfly-guard', 'rolling-back-take-from-half-butterfly', '롤링 백 테이크 (버터플라이 하프)', 'Rolling Back Take from Half Butterfly', array['구르며 백 잡기']::text[], array['언더훅을 깊게 잡고 상대 등 뒤로 머리를 넣는다','훅으로 상대를 들며 어깨 너머로 구른다','구르면서 상대 등 뒤로 나온다','훅을 넣고 백']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph half-butterfly/bottom (기 시도 4)', 18),
  ('butterfly-guard', 'pass-butterfly-hook-control', '버터플라이 훅 컨트롤 패스', 'Pass Butterfly Hook Control', array['훅 잡혀도 패스']::text[], array['상대 훅 발을 손으로 바닥에 누른다','반대쪽 엉덩이를 뒤로 빼 들리지 않게 한다','무릎을 상대 허벅지 위로 올린다','니슬라이스로 사이드']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph butterfly-hook-control/top (기 시도 5)', 19),
  ('butterfly-guard', 'john-wayne-sweep', '존 웨인 스윕', 'John Wayne Sweep', array['존웨인 스윕']::text[], array['하프 버터플라이에서 상대 먼 쪽 무릎 뒤를 손으로 잡는다','훅으로 상대 다리를 들어 올린다','반대 손으로 상대 겨드랑이나 허리띠를 잡고 밀어 굴린다','따라 올라가 마운트']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph butterfly-hook-control/bottom (기 시도 2)', 20),
  ('de-la-riva', 'de-la-riva-guard', '데라히바 가드', 'De La Riva Guard', array['DLR','데라']::text[], array['상대 한쪽 다리 바깥으로 내 다리를 감아 발을 상대 골반 앞에 건다','같은 쪽 손으로 발목(또는 바지 끝)을 잡는다','반대 발은 상대 허벅지나 골반에 대어 거리를 지킨다','반대 손으로 소매나 깃을 잡아 상체를 컨트롤한다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJ Commons §5.3 · BJJGraph', 1),
  ('de-la-riva', 'de-la-riva-sweep', '데라히바 스윕', 'De La Riva Sweep', array['DLR 스윕']::text[], array['데라히바 훅 · 발목 · 소매 그립을 잡는다','골반에 댄 발로 밀며 발목을 당겨 상대를 한 발에 서게 만든다','훅 다리로 상대 다리를 들어 올리며 소매를 당긴다','넘어가면 발목을 놓지 않고 따라 올라가 패스 자세로']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph de-la-riva-guard/bottom 1위', 2),
