  ('x-guard', 'tomahawk-sweep', '토마호크 스윕', 'Tomahawk Sweep', array['X가드 토마호크']::text[], array['X 가드에서 어깨에 얹은 다리를 반대쪽으로 넘긴다','안쪽 훅으로 상대 반대 다리를 들어 올린다','상대가 등으로 넘어진다','위로 올라와 마운트']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph x-guard/bottom (기 시도 8)', 3),
  ('x-guard', 'x-guard-technical-stand-up', 'X 가드 → 일어나기', 'X-Guard Technical Stand Up', array['X가드 스탠드업']::text[], array['상대 다리를 안은 채 한 손으로 바닥을 짚는다','엉덩이를 들고 안쪽 다리를 빼서 일어난다','상대 다리를 든 채 서서 밀어 눕힌다','패스 자세']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph x-guard/bottom (기 시도 10)', 4),
  ('x-guard', 'x-guard-to-single-leg-x', 'X 가드 → 싱글 레그 X', 'X-Guard to Single Leg X', array['SLX 전환']::text[], array['어깨에 얹은 다리를 내려 발목을 가슴에 안는다','바깥 다리를 상대 골반에 걸고 안쪽 다리는 허벅지 안쪽','상대 다리를 가슴 쪽으로 당긴다','싱글 레그 X']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph x-guard/bottom (기 시도 11)', 5),
  ('x-guard', 'ankle-lock-from-x-guard', '앵클락 (X 가드)', 'Ankle Lock from X-Guard', array['발목 꺾기','스트레이트 앵클락']::text[], array['X 가드에서 상대 발목을 겨드랑이에 끼워 길로틴처럼 감는다','손목을 가슴에 붙여 그립을 조인다','감은 팔 쪽으로 몸을 돌리며 눕는다','엉덩이를 밀며 뒤로 당겨 발목을 편다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph x-guard/bottom (기 시도 6)', 6),
  ('x-guard', 'standing-escape-from-x-guard', 'X 가드 빠져나오기 (서서)', 'Standing Escape from X-Guard', array['X가드 이스케이프']::text[], array['어깨에 얹힌 다리를 뒤로 빼며 엉덩이를 낮춘다','상대 훅 다리를 손으로 눌러 떼어낸다','다리를 빼며 뒤로 물러선다','다시 패스 자세']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph x-guard/top (기 시도 17)', 7),
  ('x-guard', 'knee-pin-from-x-guard', '무릎 눌러 X 가드 패스', 'Knee Pin from X-Guard', array['X가드 니핀']::text[], array['어깨에 얹힌 다리를 내려 상대 다리 위에 무릎으로 앉는다','상대 안쪽 훅 다리를 손으로 눌러 뺀다','하프가드 위로 자리 잡는다','니슬라이스']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph x-guard/top (기 시도 16)', 8),
  ('x-guard', 'step-over-from-x-guard', '스텝 오버 (X 가드 상대)', 'Step Over from X-Guard', array['X가드 스텝오버']::text[], array['얹힌 다리를 상대 머리 위로 넘겨 돌린다','상대 훅이 풀리면 몸을 돌려 상대 옆으로','무릎을 상대 옆구리에 붙인다','사이드']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph x-guard/top (기 시도 10)', 9),
  ('x-guard', 'smash-pass-from-x-guard', '스매시 패스 (X 가드 상대)', 'Smash Pass from X-Guard', array['X가드 스매시']::text[], array['체중을 상대 위로 떨어뜨려 훅을 뭉갠다','상대 무릎을 한쪽으로 모아 누른다','얹힌 다리를 빼낸다','사이드']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph x-guard/top (기 시도 8)', 10),
  ('x-guard', 'single-leg-x-guard', '싱글 레그 X 가드', 'Single Leg X Guard', array['SLX','싱글렉 X']::text[], array['상대 한쪽 발목을 겨드랑이에 안는다','같은 쪽 다리를 상대 다리 안쪽에서 돌려 발을 골반에 건다(중앙선을 넘지 않는다)','반대 다리는 허벅지 안쪽을 감는다','발목을 가슴으로 당기며 상대 무릎을 바깥으로 돌린다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 11),
  ('x-guard', 'single-leg-x-sweep', '싱글 레그 X 스윕', 'Single Leg X Sweep', array['SLX 스윕']::text[], array['발목을 안고 골반 발로 밀며 엉덩이를 든다','상대 무릎을 바깥으로 틀어 넘어뜨린다','상대가 앉으면 다리를 든 채 일어난다','패스 자세']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph single-leg-x-guard/bottom (기 시도 26)', 12),
  ('x-guard', 'heel-grab-sweep', '힐 그랩 스윕', 'Heel Grab Sweep', array['뒤꿈치 잡아 넘기기']::text[], array['싱글 레그 X에서 상대 반대 발 뒤꿈치를 손으로 잡는다','골반 발로 밀며 뒤꿈치를 당긴다','상대가 뒤로 넘어진다','일어나 사이드']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph single-leg-x-guard/bottom (기 시도 9)', 13),
  ('x-guard', 'slx-to-x-guard', '싱글 레그 X → X 가드', 'SLX to X-Guard', array['X가드 전환']::text[], array['상대 반대 다리 아래로 머리를 넣는다','안은 다리를 어깨에 얹는다','반대 다리로 X 모양 훅','X 가드']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph single-leg-x-guard/bottom (기 시도 12)', 14),
  ('x-guard', 'straight-ankle-lock', '스트레이트 앵클락', 'Straight Ankle Lock', array['앵클락','발목 꺾기','풋락']::text[], array['상대 발목을 겨드랑이에 끼우고 팔로 아킬레스 위를 감는다','손목을 가슴에 붙여 그립을 조인다(정강이 아니라 발목에)','감은 팔 쪽으로 몸을 돌려 눕는다','엉덩이를 앞으로 밀며 가슴을 펴 발목을 편다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 15),
  ('x-guard', 'ankle-lock-escape', '앵클락 빠져나오기', 'Ankle Lock Escape', array['앵클락 디펜스']::text[], array['바로 앉아 상대 가까운 팔을 잡아 못 눕게 한다','발끝을 위로 세워 발목이 안 펴지게 한다','반대 발로 상대 엉덩이나 발목을 밀며 다리를 뺀다','위로 올라가 패스']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 16),
  ('x-guard', 'knee-extraction', '무릎 빼기 (앵클락 상대)', 'Knee Extraction from Ankle Lock', array['무릎 빼서 서기']::text[], array['잡힌 다리 무릎을 상대 다리 사이에서 빼며 일어선다','상대 훅을 손으로 눌러 떼어낸다','뒤로 물러선다','스탠딩']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph straight-ankle-lock-control/top (기 시도 16)', 17),
  ('x-guard', 'standing-escape-from-slx', '싱글 레그 X 빠져나오기 (서서)', 'Standing Escape from SLX', array['SLX 이스케이프']::text[], array['잡힌 발의 무릎을 바깥으로 돌리지 않게 안쪽으로 유지한다','상대 골반 발을 손으로 눌러 떼어낸다','다리를 빼며 뒤로 물러난다','다시 패스 자세']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph single-leg-x-guard/top (기 시도 29)', 18),
  ('x-guard', 'backstep-from-single-leg-x', '백스텝 (싱글 레그 X 상대)', 'Backstep from Single Leg X', array['SLX 백스텝']::text[], array['잡힌 다리를 뒤로 돌리며 몸을 돌린다','상대 다리를 손으로 눌러 둔다','상대 옆으로 돌아 들어간다','사이드']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph single-leg-x-guard/top (기 시도 21)', 19),
  ('x-guard', 'reverse-x-guard', '리버스 X 가드', 'Reverse X-Guard', array['리버스 엑스']::text[], array['상대 다리 아래로 들어가 한 다리를 어깨에 얹되 몸은 반대로 향한다','안쪽 다리로 상대 반대 무릎 뒤를 건다','바깥 다리는 허벅지를 민다','발목을 당겨 균형을 뺏는다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 20),
  ('x-guard', 'reverse-x-guard-sweep', '리버스 X 가드 스윕', 'Reverse X-Guard Sweep', array['리버스 X 스윕']::text[], array['얹은 다리를 안고 훅으로 상대 다리를 든다','상대 체중이 뜨면 옆으로 넘긴다','굴러 올라온다','마운트']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph reverse-x-guard/bottom (기 시도 28)', 21),
  ('x-guard', 'elevation-sweep-to-mount', '엘리베이션 스윕 (리버스 X)', 'Elevation Sweep to Mount', array['들어 올려 넘기기']::text[], array['양 다리로 상대 다리를 들어 올린다','상대가 손을 짚으면 그쪽 발목을 당긴다','등으로 넘긴다','마운트']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph reverse-x-guard/bottom (기 시도 14)', 22),
  ('x-guard', 'reverse-x-to-back-take', '리버스 X → 백 테이크', 'Reverse X to Back Take', array['리버스 X 백']::text[], array['얹은 다리를 안고 상대 뒤로 돈다','허리띠를 잡고 상대를 앉힌다','등 뒤로 나와 훅','백']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph reverse-x-guard/bottom (기 시도 11)', 23),
