  ('half-guard', 'half-guard-basics', '하프가드 (자세 · 프레임)', 'Half Guard (Basics & Frames)', array['하프','반 가드']::text[], array['상대 한쪽 다리를 내 양 다리로 감아 발목을 잠근다','감은 다리 쪽으로 옆으로 돌아 눕는다 — 등이 바닥에 평평하면 진다','위쪽 팔뚝은 상대 목, 아래 팔뚝은 골반에 대어 프레임을 만든다(손바닥이 아니라 뼈로)','밀기 전에 먼저 브릿지로 상대 체중을 띄운 뒤 엉덩이를 빼서 공간을 만든다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJ Commons §3.1~3.2', 1),
  ('half-guard', 'knee-shield-half-guard', '니 쉴드 하프가드', 'Knee Shield Half Guard', array['제트 가드','Z 가드','니실드']::text[], array['하프가드에서 위쪽 무릎을 상대 배나 골반 앞에 가로로 세운다(낮은 니 쉴드)','아래 다리는 상대 다리를 계속 감아 둔다','같은 쪽 손은 내 무릎, 반대 손은 상대 이두를 잡아 거리를 지킨다','상대가 무릎을 밀어 치우면 그 팔을 따라 들어가 언더훅으로 바꾼다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJ Commons §3.3 · BJJGraph half-guard/bottom 1위', 2),
  ('half-guard', 'half-guard-underhook', '하프가드 언더훅 잡기', 'Winning the Underhook from Half Guard', array['언더훅 싸움','언더훅']::text[], array['팔로 먼저 뻗지 말고 무릎을 들어 올려 상대 몸을 위로 밀어 공간을 만든다','생긴 공간으로 팔을 넣어 상대 겨드랑이 아래를 감는다','손은 상대 등 위가 아니라 골반 가까이, 팔꿈치는 몸에 붙여 짧게 잡는다','언더훅을 잡으면 머리를 상대 겨드랑이 밑으로 빼고 스윕이나 백 테이크로 간다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJ Commons §3.4 ''다리로 공간을 만들고 팔이 채운다''', 3),
  ('half-guard', 'half-guard-underhook-sweep', '하프가드 언더훅 스윕 (올드 스쿨)', 'Half Guard Underhook Sweep (Old School)', array['언더훅 스윕','올드 스쿨 스윕']::text[], array['하프가드에서 언더훅을 잡고 옆으로 돌아 눕는다','머리를 상대 겨드랑이 아래로 넣어 자세를 낮춘다','언더훅 팔로 상대 다리를 안아 내리고(또는 발목을 잡고) 중심을 뺏는다','앞으로 밀며 올라와 탑으로 간다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJ Commons §3.5 · BJJGraph', 4),
  ('half-guard', 'half-guard-back-take', '하프가드 백 테이크', 'Back Take from Half Guard', array['하프에서 백 잡기']::text[], array['언더훅을 잡고 옆으로 돌아 머리를 상대 겨드랑이 아래로 뺀다','무릎을 세워 상대 등 뒤로 돌아 올라온다(도그파이트)','한 손으로 허리띠나 허리를 잡고 가슴을 상대 등에 붙인다','훅을 넣고 시트벨트를 잡아 백 컨트롤을 완성한다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJ Commons §3.5 · BJJGraph 3위', 5),
  ('half-guard', 'half-guard-recovery', '하프가드에서 가드 회복', 'Half Guard to Full Guard Recovery', array['가드 리커버리','풀 가드 복귀']::text[], array['상대 목과 골반에 프레임을 만든다','브릿지 → 엉덩이 빼기(쉬림프)를 한 번이 아니라 두 번 한다','감아 둔 다리 쪽 무릎을 상대 배 앞으로 가져온다','반대 다리를 상대 허리 위로 넘겨 클로즈드 가드나 버터플라이로 돌아온다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJ Commons §3.2 ''더블 힙 이스케이프'' · BJJGraph', 6),
  ('half-guard', 'deep-half-guard', '딥 하프가드', 'Deep Half Guard', array['딥 하프']::text[], array['하프가드에서 상대 다리 아래로 깊게 파고들어 허벅지가 내 가슴 위에 오게 한다','감은 다리 쪽 팔로 상대 허벅지를 안고 머리는 상대 다리 아래로 숨긴다','반대 손으로 상대 발목이나 허리띠를 잡아 자세를 고정한다','상대 다리를 들어 올리며 돌아 위로 올라온다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph half-guard/bottom', 7),
  ('half-guard', 'kimura-half-guard', '기무라 (하프가드)', 'Kimura from Half Guard', array['하프 기무라','기무라 트랩']::text[], array['상대가 내 머리를 누르거나 바닥을 짚은 손목을 잡는다','반대 팔로 상대 윗팔을 감아 내 손목을 잡는다(8자 그립)','옆으로 돌아 팔꿈치를 몸에 붙이고 상대 어깨를 바닥 쪽으로 누른다','바로 안 꺾이면 스윕이나 백 테이크로 잇는다(기무라 트랩)']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJ Commons §3.6 · §11.3', 8),
  ('half-guard', 'half-guard-frames', '하프가드 프레임 · 더블 힙 이스케이프', 'Half Guard Frames & Double Hip Escape', array['하프 프레임','브릿지 앤 프레임']::text[], array['위 팔뚝은 상대 목, 아래 팔뚝은 골반(손바닥 말고 뼈로)','먼저 브릿지로 상대 체중을 띄운다','프레임으로 공간을 지키며 엉덩이를 뺀다(한 번 더)','무릎을 넣거나 언더훅을 잡는다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 9),
  ('half-guard', 'z-guard', 'Z 가드', 'Z-Guard', array['제트 가드','높은 니 쉴드']::text[], array['니 쉴드 무릎을 상대 가슴이나 어깨 높이로 올린다','아래 다리는 상대 다리를 감는다','같은 쪽 팔로 상대 머리를 밀어 프레임','반대 손으로 소매나 깃을 잡고 스윕 · 회복을 노린다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 10),
  ('half-guard', 'z-guard-sweep', 'Z 가드 스윕', 'Z-Guard Sweep', array['제트 가드 스윕']::text[], array['깃이나 소매를 잡고 니 쉴드로 상대를 민다','상대가 밀고 들어오면 니 쉴드를 풀어 그 다리로 상대 허벅지를 든다','아래 다리로 상대 발목을 걸어 당긴다','넘기고 위로']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph z-guard/bottom (기 시도 17)', 11),
  ('half-guard', 'z-guard-to-half-guard', 'Z 가드 → 하프가드 (언더훅)', 'Z-Guard to Half Guard', array['니 쉴드 풀어 언더훅']::text[], array['상대가 니 쉴드를 밀어 치우면 그 팔을 따라 들어간다','팔을 상대 겨드랑이 아래로 넣어 언더훅','엉덩이를 상대 쪽으로 당긴다','언더훅 스윕이나 백 테이크']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph z-guard/bottom (기 시도 15)', 12),
  ('half-guard', 'knee-shield-to-closed-guard', '니 쉴드 → 클로즈드 가드', 'Knee Shield to Closed Guard', array['니 쉴드 리가드']::text[], array['니 쉴드로 거리를 만든다','감은 다리를 풀어 상대 허리 위로 넘긴다','반대 다리도 감는다','클로즈드 가드']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph knee-shield-half-guard/bottom (기 시도 8)', 13),
  ('half-guard', 'kimura-from-knee-shield', '기무라 (니 쉴드)', 'Kimura from Knee Shield Half Guard', array['니 쉴드 기무라']::text[], array['상대가 니 쉴드를 밀려고 짚은 손목을 잡는다','반대 팔로 윗팔을 감아 내 손목을 잡는다','니 쉴드로 상대 상체를 밀며 어깨를 눌러 둔다','팔을 등 뒤로']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 14),
  ('half-guard', 'sweep-from-knee-shield', '니 쉴드 스윕', 'Sweep from Knee Shield', array['니 쉴드 넘기기']::text[], array['깃과 소매를 잡는다','니 쉴드 다리를 풀어 상대 허벅지 안쪽을 든다','아래 다리로 상대 발목을 걸어 당긴다','넘기고 마운트']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph knee-shield-half-guard/bottom (기 시도 4)', 15),
  ('half-guard', 'old-school-sweep', '올드 스쿨 스윕', 'Old School Sweep', array['올드스쿨']::text[], array['언더훅을 잡고 옆으로 돌아 머리를 상대 겨드랑이 아래로','언더훅 팔로 상대 먼 쪽 발목을 잡는다','발목을 당기며 앞으로 밀고 올라온다','사이드 탑']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph old-school/bottom (기 시도 24)', 16),
  ('half-guard', 'defend-old-school-sweep', '올드 스쿨 스윕 방어', 'Defend Old School Sweep', array['올드스쿨 디펜스']::text[], array['상대가 언더훅 잡으면 바로 위저(오버훅)로 팔을 감는다','잡힌 발목 쪽 다리를 뒤로 빼 펴며 엉덩이를 낮춘다','크로스페이스로 상대 머리를 눌러 둔다','다시 하프 탑']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph old-school/top (기 시도 16)', 17),
  ('half-guard', 'dogfight-position', '도그파이트', 'Dogfight Position', array['도그 파이트']::text[], array['언더훅을 잡고 무릎으로 일어나 상대 다리를 안는다','상대도 위저로 버티면 둘 다 네발 자세(도그파이트)','머리를 상대 옆구리에 붙인다','상대 반응에 따라 스윕 · 백 테이크 · 재하프']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph leg-weave/bottom (기 시도 14)', 18),
  ('half-guard', 'dogfight-sweep', '도그파이트 스윕', 'Dogfight Sweep', array['도그파이트에서 넘기기']::text[], array['상대가 몸을 바깥으로 돌리면 먼 쪽 발목을 잡아 당긴다','상대가 내 쪽으로 돌면 무릎을 밀어 엉덩이를 바닥으로','어깨와 머리로 밀어붙인다','위로 올라와 사이드']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph dogfight-position/bottom (기 시도 28)', 19),
  ('half-guard', 'forward-drive-sweep-from-dogfight', '도그파이트 전진 스윕', 'Forward Drive Sweep from Dogfight', array['밀어 넘기기']::text[], array['상대 다리를 안은 채 어깨를 상대 골반에 붙인다','발로 바닥을 밀며 앞으로 돌진한다','상대가 뒤로 넘어진다','마운트나 사이드']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph dogfight-position/bottom (기 시도 13)', 20),
  ('half-guard', 're-pull-half-guard-from-dogfight', '도그파이트 → 하프가드 복귀', 'Re-pull Half Guard from Dogfight', array['하프 다시 잡기']::text[], array['스윕이 막히면 상대 다리를 안은 채 엉덩이를 바닥에 앉힌다','안은 다리를 내 양 다리로 감는다','옆으로 돌아 눕는다','언더훅 하프가드']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph dogfight-position/bottom (기 시도 16)', 21),
  ('half-guard', 're-flatten-from-dogfight', '도그파이트 상대 다시 눕히기', 'Re-flatten from Dogfight', array['도그파이트 탑 디펜스']::text[], array['위저로 상대 어깨를 눌러 둔다','잡힌 다리를 뒤로 빼며 엉덩이를 낮춘다','크로스페이스로 머리를 눌러 눕힌다','하프 탑']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph dogfight-position/top (기 시도 38)', 22),
  ('half-guard', 'crossface-from-dogfight', '크로스페이스 (도그파이트 탑)', 'Crossface from Dogfight', array['도그파이트 크로스페이스']::text[], array['위저를 유지한 채 반대 팔로 상대 얼굴을 반대쪽으로 민다','상대 등이 바닥으로 가게 돌린다','다리를 빼며 가슴을 붙인다','사이드']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph dogfight-position/top (기 시도 32)', 23),
  ('half-guard', 'snap-down-from-dogfight', '스냅 다운 (도그파이트 탑)', 'Snap Down from Dogfight', array['도그파이트 스냅다운']::text[], array['위저 반대 손으로 상대 목 뒤를 잡는다','위저와 함께 아래로 강하게 낚아챈다','상대 머리가 바닥으로 가면 가슴으로 누른다','프론트 헤드락']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph dogfight-position/top (기 시도 30)', 24),
  ('half-guard', 'flattened-half-guard', '눌린 하프가드에서 회복', 'Flattened Half Guard Recovery', array['플랫 하프','눌렸을 때']::text[], array['상대가 언더훅 · 크로스페이스로 눌렀을 때 손을 상대 팔꿈치에 댄다','브릿지하며 어깨를 띄운다','팔꿈치를 가슴에 붙여 작게 돌려 언더훅을 되찾는다','옆으로 돌아 니 쉴드나 언더훅 하프']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 25),
  ('half-guard', 'deep-half-entry-from-flattened', '눌린 하프 → 딥 하프', 'Deep Half Entry from Flattened', array['눌렸을 때 딥 하프']::text[], array['상대 다리 아래로 머리를 넣는다','엉덩이를 빼며 상대 허벅지 아래로 깊게 들어간다','허벅지를 안는다','딥 하프']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph flattened-half-guard/bottom (기 시도 6)', 26),
