  ('half-guard', 'complete-pass-from-quarter', '쿼터 가드 패스', 'Complete Pass from Quarter', array['쿼터 패스']::text[], array['크로스페이스로 상대 머리를 돌린다','걸린 발목을 반대 발로 밀어 빼낸다','체중을 가슴에 싣는다','사이드']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph quarter-guard/top (기 시도 19)', 37),
  ('half-guard', 'knee-through-from-quarter', '쿼터 가드 → 마운트', 'Knee Through from Quarter', array['쿼터 니 스루']::text[], array['크로스페이스로 상대를 눌러 둔다','걸린 발을 빼며 무릎을 상대 배 위로 미끄러뜨린다','반대 다리를 넘긴다','마운트']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph quarter-guard/top (기 시도 13)', 38),
  ('half-guard', 'sweep-from-quarter-guard', '쿼터 가드 스윕', 'Sweep from Quarter Guard', array['쿼터 스윕']::text[], array['언더훅을 잡고 옆으로 돈다','걸린 발목을 당겨 상대 중심을 뺏는다','앞으로 밀며 올라온다','사이드']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph quarter-guard/bottom (기 시도 10)', 39),
  ('half-guard', 'kimura-from-quarter-guard', '기무라 (쿼터 가드 탑)', 'Kimura from Quarter Guard Top', array['쿼터 기무라']::text[], array['상대가 프레임 짚은 손목을 잡는다','반대 팔을 아래로 넣어 내 손목','상대 어깨를 누른다','팔을 등 뒤로']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph quarter-guard/top (기 시도 5)', 40),
  ('half-guard', 'half-guard-to-x-guard', '하프가드 → X 가드', 'Half Guard to X-Guard', array['하프 X가드']::text[], array['상대가 서면 감은 다리 아래로 머리를 넣는다','반대 다리로 상대 반대 허벅지를 건다','상대 다리를 어깨에 얹는다','X 가드']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph half-guard/bottom (기 시도 4)', 41),
  ('half-guard', 'back-door-escape-from-half', '백 도어 이스케이프 (하프)', 'Back Door Escape from Half Guard', array['백도어']::text[], array['상대가 패스하며 체중이 앞으로 쏠리면 상대 다리 아래로 몸을 뺀다','상대 엉덩이 뒤로 빠져나온다','터틀이나 등 뒤로','백 테이크']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 42),
  ('half-guard', 'knee-torque-sweep', '니 토크 스윕', 'Knee Torque Sweep', array['무릎 비틀기 스윕']::text[], array['감은 상대 다리를 양 다리로 비틀어 무릎을 바깥으로 돌린다','상대가 균형을 잃으면 언더훅으로 민다','옆으로 넘긴다','마운트']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph half-guard/bottom (기 시도 1)', 43),
  ('half-guard', 'loop-choke-from-half-top', '루프 초크 (하프 탑)', 'Loop Choke from Half Guard Top', array['하프 루프 초크']::text[], array['상대 깃을 잡고 상대가 언더훅 잡으러 머리를 숙일 때','깃 잡은 팔을 돌려 상대 목을 감는다','반대 팔을 상대 등 뒤로','몸을 돌리며 조인다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 44),
  ('half-guard', 'leg-weave-pass', '레그 위브 패스', 'Leg Weave Pass', array['레그 레이스','다리 엮기']::text[], array['한 팔을 상대 위쪽 다리 아래, 아래 다리 위로 넣어 바닥을 짚는다(엮기)','머리와 어깨를 낮춰 상대 무릎을 모은다','스프롤로 감긴 다리를 뺀다','다리를 돌아 사이드']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph half-guard/top (기 시도 27)', 45),
  ('half-guard', 'body-lock-pass', '바디락 패스', 'Body Lock Pass', array['보디락 패스']::text[], array['양팔로 상대 허리를 감아 손을 맞잡는다','가슴을 붙이고 엉덩이를 낮춘다','상대 다리를 한쪽으로 몰아 깔아뭉갠다','다리를 빼며 사이드']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph half-guard/top (기 시도 17)', 46),
  ('half-guard', 'crossface-to-combat-base', '크로스페이스 → 컴뱃 베이스', 'Crossface to Combat Base', array['하프 탑 리셋']::text[], array['크로스페이스로 상대를 눌러 둔다','감긴 다리 무릎을 세워 컴뱃 베이스 자세','반대 손으로 상대 무릎을 누른다','니슬라이스로']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph half-guard/top (기 시도 17)', 47),
  ('half-guard', 'half-guard-whizzer-counter', '하프 탑 위저 카운터', 'Half Guard Whizzer Counter', array['언더훅 잡혔을 때']::text[], array['상대가 언더훅 잡으면 그 팔을 위에서 감는다','엉덩이를 뒤로 빼 상대가 못 일어나게','팔을 조여 어깨를 바닥으로','오버훅 컨트롤']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph half-guard/top (기 시도 4)', 48),
  ('half-guard', 'half-guard-to-leg-weave', '하프가드 → 레그 위브', 'Half Guard to Leg Weave', array['레그 위브 진입']::text[], array['상대 니 쉴드 다리 아래로 팔을 넣는다','아래 다리 위를 지나 바닥을 짚는다','머리를 낮춰 무릎을 모은다','레그 위브 패스']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph half-guard/top (기 시도 3)', 49),
  ('passing', 'posture-in-closed-guard', '클로즈드 가드 안에서 자세 잡기', 'Posture inside Closed Guard', array['포스처','가드 안 자세']::text[], array['허리를 펴고 머리를 세워 상대가 당기지 못하게 한다','양손은 상대 갈비(골반 아님)를 누르거나 깃 · 허리띠를 잡는다','팔꿈치를 몸에 붙여 암바 · 기무라에 팔을 내주지 않는다','무릎을 넓게 벌려 베이스를 만든 뒤 가드 열기로 간다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJ Commons §2.5 · BJJGraph closed-guard/top 1위', 1),
  ('passing', 'closed-guard-break-knee', '가드 열기 (무릎 쐐기)', 'Closed Guard Break (Knee Wedge)', array['가드 브레이크','가드 오픈']::text[], array['자세를 세운 채 한 무릎을 상대 꼬리뼈 아래에 쐐기처럼 넣는다','뒤로 앉으며 상대 발목 잠금에 압력을 건다','한 손으로 상대 무릎을 눌러 다리를 연다 — 반대 팔은 상대 허벅지를 계속 막는다(두 팔을 동시에 뒤로 빼지 않는다)','열리면 무릎을 다리 사이로 넣어 니슬라이스로 잇는다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJ Commons §2.5 ''웨지 패스''', 2),
  ('passing', 'standing-guard-break', '스탠딩 가드 브레이크', 'Standing Closed Guard Break', array['서서 가드 열기']::text[], array['상대 양 이두를 바닥에 눌러 고정하고 한 발씩 세워 일어선다','허리를 펴고 뒤로 한 발 물러나며 상대 허벅지 안쪽을 양손으로 누른다','다리가 풀리면 한 다리를 내 허벅지 사이에 끼우거나 어깨에 걸어 컨트롤한다','바로 니슬라이스나 토레안도로 잇는다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJ Commons §2.5 ''스탠딩 패스''', 3),
  ('passing', 'knee-slice-pass', '니슬라이스 패스', 'Knee Slice Pass', array['니컷','니스루','니 스플릿','knee cut']::text[], array['한 무릎(정강이)을 상대 허벅지 안쪽 위에 올리고 뒷발은 세워 미는 힘을 만든다','같은 쪽 팔로 언더훅(또는 깃)을 잡아 상대 어깨를 바닥에 붙인다','정강이를 바닥까지 미끄러뜨리며 다리를 끝까지 빼낸다 — 다리가 다 빠지기 전에 골반을 돌리지 않는다','빠지면 골반을 돌려 가슴을 붙이고 사이드 컨트롤로']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJ Commons §4.2 (안전 규칙) · BJJGraph 거의 모든 가드에서 상위', 4),
  ('passing', 'toreando-pass', '토레안도 패스', 'Toreando Pass', array['불 패스','토레아도','투우사 패스']::text[], array['양손으로 상대 무릎 뒤 또는 바지 끝을 잡는다','한쪽 무릎을 바닥으로 눌러 ''죽이고'' 반대쪽으로 다리를 밀어 넘긴다','발을 옆으로 옮겨 상대 옆으로 돌아 들어간다','어깨를 가슴에 떨어뜨리고 머리를 컨트롤해 사이드 컨트롤로']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJ Commons §5.6 · BJJGraph open-guard/top 1위', 5),
  ('passing', 'leg-drag', '레그 드래그', 'Leg Drag Pass', array['렉 드래그','다리 끌기']::text[], array['상대 한쪽 발목(또는 바지 끝)을 잡는다','그 다리를 내 반대쪽 엉덩이 옆으로 끌어와 허벅지 사이에 끼운다','같은 쪽 무릎을 상대 엉덩이 옆에 붙여 돌지 못하게 막는다','상체를 숙여 가슴을 누르며 사이드 컨트롤로']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph open-guard/top 3위', 6),
  ('passing', 'double-under-pass', '더블 언더 패스 (스택)', 'Double Under / Stack Pass', array['스택 패스','더블언더']::text[], array['양팔을 상대 다리 아래로 넣고 손을 모아 허리띠나 깃을 잡는다','상대 엉덩이를 들어 내 허벅지 위에 얹는다(스택)','어깨로 다리를 머리 쪽으로 눌러 공간을 뺏는다','한쪽으로 돌며 다리를 빼내고 사이드 컨트롤로']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJ Commons §5.6 · BJJGraph', 7),
  ('passing', 'over-under-pass', '오버 언더 패스', 'Over Under Pass', array['오버언더']::text[], array['한 팔은 상대 다리 아래(언더), 반대 팔은 다리 위(오버)로 감는다','머리를 오버 쪽 상대 엉덩이 옆에 붙이고 가슴을 낮춘다','오버 쪽 다리를 내 다리 사이에 끼우고 발끝으로 서서 언더 쪽 다리를 어깨로 든다','다리를 바닥에 눌러 두고 돌아 나와 사이드 컨트롤로']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJ Commons §5.6', 8),
  ('passing', 'long-step-pass', '롱 스텝 패스', 'Long Step Pass', array['롱스텝']::text[], array['상대 무릎과 반대 어깨(또는 깃)를 잡아 거리를 잡는다','한 다리를 뒤로 길게 뻗으며 엉덩이를 바닥 쪽으로 낮춘다(스프롤)','상대 다리를 바닥으로 눌러 훅이 걸리지 않게 한다','뻗은 다리를 돌려 상대 옆으로 들어가 사이드 컨트롤로']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 여러 가드 top 공통', 9),
  ('passing', 'half-guard-pass', '하프가드 패스 (크로스페이스 · 언더훅)', 'Half Guard Pass (Crossface & Underhook)', array['하프 패스','크로스페이스 패스','언더훅 패스']::text[], array['언더훅을 먼저 잡고 상대 어깨를 바닥에 눌러 평평하게 만든다','반대 팔로 크로스페이스를 걸어 상대 얼굴을 반대쪽으로 돌린다','내 자유로운 다리로 상대 먼 쪽 다리를 걸어 눌러 가드 회복을 막는다','감긴 다리를 빼내고 가슴을 붙여 사이드 컨트롤로']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJ Commons §4.1 (언더훅 → 눕히기 → 머리 → 먼 다리 → 빼기)', 10),
  ('passing', 'smash-pass', '스매시 패스', 'Smash Pass', array['스매쉬 패스','하프 스매시']::text[], array['하프가드 위에서 상대 니 쉴드 무릎을 바닥으로 누른다','상대 양 무릎이 겹치게 체중으로 눌러 골반을 비튼다','팔꿈치를 바닥에 가깝게 두고 머리로 상대 가슴을 누른다','감긴 다리를 빼며 돌아 사이드 컨트롤로']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJ Commons §4.3 · BJJGraph half-guard/top 2위', 11),
  ('passing', 'butterfly-pass', '버터플라이 패스', 'Butterfly Guard Pass', array['버터플라이 가드 패스']::text[], array['양 훅에 체중을 똑같이 싣고 걸어 들어가지 않는다 — 한쪽을 고른다','한 손으로 상대 한쪽 훅(발)을 바닥에 밀어 내린다','반대쪽 엉덩이를 뒤로 넓게 빼서 남은 훅이 들지 못하게 한다','하프가드로 내려앉아 니슬라이스로 잇는다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJ Commons §5.1', 12),
  ('passing', 'combat-base', '컴뱃 베이스', 'Combat Base', array['콤뱃 베이스','한 무릎 세우기']::text[], array['상대 오픈 가드 앞에서 한 무릎은 바닥, 반대 무릎은 세운다','세운 무릎을 상대 다리 사이에 둔다','허리를 펴고 손은 상대 무릎이나 깃','니슬라이스 · 헤드쿼터로 잇는다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 13),
  ('passing', 'knee-slide-from-combat-base', '니 슬라이드 (컴뱃 베이스)', 'Knee Slide from Combat Base', array['컴뱃 베이스 니슬라이스']::text[], array['세운 무릎을 상대 허벅지 안쪽으로 올린다','깃이나 언더훅을 잡는다','정강이로 미끄러진다','사이드']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph combat-base/top (기 시도 22)', 14),
  ('passing', 'pressure-pass', '프레셔 패스', 'Pressure Pass', array['압박 패스']::text[], array['가슴을 상대 가슴에 붙이고 엉덩이를 낮춘다','상대 다리를 한쪽으로 몰아 체중으로 누른다','다리를 천천히 빼낸다','사이드']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph combat-base/top (기 시도 15)', 15),
  ('passing', 'combat-base-to-headquarters', '컴뱃 베이스 → 헤드쿼터', 'Combat Base to Headquarters', array['헤드쿼터 진입']::text[], array['세운 발을 상대 다리 사이에 두고 일어선다','상대 한 다리를 내 허벅지 사이에 끼운다','반대 다리는 손으로 누른다','헤드쿼터']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph combat-base/top (기 시도 15)', 16),
