  ('passing', 'knee-slice-from-closed-guard', '니슬라이스 (클로즈드 가드 열고)', 'Knee Slice from Closed Guard', array['가드 열고 니슬라이스']::text[], array['무릎 쐐기로 가드를 연다','무릎을 상대 허벅지 안쪽으로','깃이나 언더훅','정강이로 미끄러져 사이드']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph closed-guard/top (기 시도 13)', 54),
  ('passing', 'knee-slice-from-seated-guard', '니슬라이스 (시팅 가드 상대)', 'Knee Slice from Seated Guard', array['앉은 가드 니슬라이스']::text[], array['앉은 상대 어깨를 밀어 눕힌다','무릎을 상대 허벅지 위로','깃을 잡는다','사이드']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph seated-guard/top (기 시도 12)', 55),
  ('passing', 'bodylock-pass-from-seated', '바디락 패스 (시팅 가드 상대)', 'Bodylock Pass from Seated', array['앉은 가드 바디락']::text[], array['앉은 상대 허리를 양팔로 안는다','가슴을 붙이고 밀어 눕힌다','다리를 한쪽으로 몰아 누른다','사이드']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph seated-guard/top (기 시도 10)', 56),
  ('passing', 'bull-pass-from-seated', '불 패스 (시팅 가드 상대)', 'Bull Pass from Seated', array['앉은 가드 토레안도']::text[], array['앉은 상대 양 무릎을 잡는다','밀어 눕히며 한쪽으로 넘긴다','반대로 돌아 들어간다','사이드']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph seated-guard/top (기 시도 9)', 57),
  ('passing', 'pass-shin-to-shin-guard', '신 투 신 가드 패스', 'Pass Shin-to-Shin Guard', array['신투신 패스']::text[], array['상대 정강이에 대인 다리를 뒤로 빼거나 바깥으로 돌린다','상대 발목 그립을 끊는다','무릎을 상대 다리 위로','니슬라이스']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph shin-to-shin-guard/top (기 시도 15)', 58),
  ('passing', 'knee-through-vs-shin-to-shin', '니 스루 (신 투 신 상대)', 'Knee Through vs Shin-to-Shin', array['신투신 니스루']::text[], array['정강이에 대인 다리 무릎을 상대 다리 안쪽으로 밀어 넣는다','깃을 잡아 상체를 누른다','무릎을 바닥으로 미끄러뜨린다','사이드']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 59),
  ('passing', 'pass-feet-on-hips-guard', '발 골반 가드 패스', 'Pass Feet on Hips Guard', array['피트온힙스 패스']::text[], array['골반에 댄 상대 발을 손으로 잡아 옆으로 넘긴다','양 무릎을 한쪽으로 모은다','돌아 들어간다','사이드']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph feet-on-hips-guard/top (기 시도 4)', 60),
  ('passing', 'counter-sweep', '카운터 스윕 (패스 중)', 'Counter Sweep', array['스윕 되치기']::text[], array['상대가 스윕을 걸면 넘어가는 방향으로 손을 짚는다','짚은 쪽으로 체중을 옮겨 버틴다','상대 다리를 눌러 무력화','바로 패스']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph open-guard/top (기 시도 3)', 61),
  ('side-control', 'side-control-maintain', '사이드 컨트롤 유지', 'Side Control (Crossface & Underhook)', array['크로스페이스','사이드 잡기']::text[], array['무릎을 상대 옆구리에 붙이고 가슴으로 상대 가슴을 누른다','머리 쪽 팔은 상대 목 아래로 넣어 먼 겨드랑이를 잡고 어깨로 턱을 밀어 얼굴을 돌린다(크로스페이스)','반대 팔은 상대 가까운 팔을 옆구리에 눌러 언더훅을 못 잡게 한다','상대가 무릎을 넣으려 하면 골반을 바닥에 떨어뜨려 막는다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJ Commons §6.1', 1),
  ('side-control', 'side-control-escape', '사이드 이스케이프 (프레임 · 쉬림프)', 'Side Control Escape (Frame & Shrimp)', array['힙 이스케이프','쉬림프']::text[], array['팔뚝 뼈로 상대 목과 골반에 프레임을 만든다','먼저 브릿지로 상대를 띄우고 프레임으로 공간을 지킨다','엉덩이를 빼서(쉬림프) 공간을 만든다 — 한 번에 안 되면 두 번','무릎을 상대와 나 사이로 넣어 가드를 되찾거나 언더훅을 잡고 일어난다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJ Commons §6.4 · BJJGraph side-control/bottom', 2),
  ('side-control', 'side-to-mount', '사이드에서 마운트 가기', 'Side Control to Mount', array['니 슬라이드 마운트','마운트 전환']::text[], array['크로스페이스로 상대 머리를 반대쪽으로 돌려 둔다','골반 쪽 무릎을 상대 배 위로 미끄러뜨린다','반대 손으로 상대 무릎이나 허벅지를 눌러 다리로 걸지 못하게 한다','무릎이 반대편 바닥에 닿으면 체중을 낮춰 마운트']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJ Commons §6.3 · BJJGraph side-control/top 1위', 3),
  ('side-control', 'americana-side', '아메리카나 (사이드)', 'Americana from Side Control', array['키락','아메리카나']::text[], array['상대 손목을 바닥에 눌러 팔꿈치가 90도로 굽혀지게 한다(손바닥은 위로)','반대 팔을 상대 팔 아래로 넣어 내 손목을 잡는다(8자 그립)','상대 팔꿈치를 몸에 붙이고 손목은 바닥에 붙여 둔다','손목을 바닥에 끌며 팔꿈치를 위로 들어 어깨를 꺾는다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJ Commons §11.4', 4),
  ('side-control', 'kimura-side', '기무라 (사이드)', 'Kimura from Side Control', array['사이드 키무라']::text[], array['상대가 내 목을 밀 때 그 손목을 잡는다','반대 팔을 상대 팔 아래로 넣어 내 손목을 잡는다(8자 그립)','상대 머리 쪽으로 돌아 무릎을 상대 머리와 팔 사이에 넣는다','팔꿈치를 몸에 붙인 채 상대 손을 등 뒤로 올려 어깨를 꺾는다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJ Commons §6.2 · §11.3', 5),
  ('side-control', 'arm-triangle', '암 트라이앵글 (헤드 앤 암)', 'Arm Triangle (Head and Arm Choke)', array['헤드 앤 암 초크','가타가타메']::text[], array['상대 팔을 머리 너머로 넘겨 목과 팔이 함께 잡히게 한다','한 팔을 상대 목 아래로 넣고 반대 손과 맞잡는다(또는 이두를 잡는다)','머리를 상대 팔 바깥쪽에 붙여 팔이 빠지지 않게 한다','반대쪽으로 넘어가 다리를 벌리고 어깨를 눌러 조인다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJ Commons §11.8', 6),
  ('side-control', 'darce-choke', '다스 초크', 'D''Arce Choke', array['다스','다르스']::text[], array['상대가 쉬림프하며 언더훅을 잡으려 할 때 그 팔 아래로 내 팔을 넣는다','넣은 팔을 상대 목 반대편까지 깊게 꿰어 넣는다','반대 팔의 이두를 잡아 8자(피겨 포)를 만들고 상대 머리를 아래로 누른다','먼 쪽 엉덩이로 눕듯 몸을 낮춰 가슴으로 머리와 팔을 함께 조인다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJ Commons §6.2 · §9.3', 7),
  ('side-control', 'arm-extraction', '팔 빼내기 (사이드 아래)', 'Arm Extraction from Side Control', array['끼인 팔 빼기']::text[], array['상대가 내 가까운 팔을 끼우면 브릿지로 체중을 띄운다','팔꿈치를 몸 쪽으로 당기며 빼낸다','빼낸 팔로 프레임','하프나 가드 회복']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph side-control/bottom (기 시도 21)', 8),
  ('side-control', 'elbow-escape-to-guard', '엘보 이스케이프 (사이드)', 'Elbow Escape to Guard', array['팔꿈치 넣어 가드 회복']::text[], array['팔꿈치를 상대 골반에 대어 프레임','엉덩이를 빼며 무릎을 상대와 나 사이로','반대 다리로 상대 다리를 감는다','하프나 풀 가드']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph side-control/bottom (기 시도 20)', 9),
  ('side-control', 'roll-to-turtle', '터틀로 돌기 (사이드)', 'Roll to Turtle', array['사이드에서 터틀']::text[], array['상대 반대쪽으로 엉덩이를 빼며 몸을 뒤집는다','팔꿈치와 무릎을 붙여 터틀','머리를 지킨다','일어서거나 가드 회복']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph side-control/bottom (기 시도 12)', 10),
  ('side-control', 'ghost-escape', '고스트 이스케이프', 'Ghost Escape from Side Control', array['고스트']::text[], array['상대가 크로스페이스 없이 눌릴 때 먼 쪽 팔을 상대 목 아래로 뺀다','상대 반대쪽으로 엉덩이를 돌리며 빠져나간다','다리를 상대 쪽으로 돌린다','오픈 가드']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 11),
  ('side-control', 'sit-out-from-side-control', '싯아웃 (사이드)', 'Sit Out from Side Control', array['사이드 싯아웃']::text[], array['언더훅을 잡고 상대 반대쪽으로 엉덩이를 뺀다','무릎으로 일어나며 다리를 상대 뒤로 뺀다','상대 옆이나 뒤로 돌아선다','터틀 탑']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph side-control/bottom (기 시도 5)', 12),
  ('side-control', 'bridge-and-roll-from-side', '브릿지 앤 롤 (사이드)', 'Bridge and Roll from Side Control', array['사이드 업파']::text[], array['상대 가까운 팔을 감싸 잡는다','발을 당겨 세우고 상대 쪽으로 강하게 브릿지','굴러 넘긴다','위로']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 13),
  ('side-control', 'armbar-from-side-control', '암바 (사이드)', 'Armbar from Side Control', array['사이드 암바']::text[], array['상대 먼 쪽 팔을 언더훅으로 잡아 가슴에 붙인다','다리를 상대 머리 쪽으로 돌려 한 다리를 머리 위로','무릎을 모아 팔을 가둔다','엉덩이를 들어 편다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph side-control/top (기 시도 5)', 14),
  ('side-control', 'far-side-armbar', '파 사이드 암바', 'Far Side Armbar', array['먼 쪽 팔 암바']::text[], array['상대 먼 쪽 팔꿈치를 당겨 내 겨드랑이에 가둔다','가까운 다리를 상대 머리 위로 넘긴다','앉으며 뒤로 눕는다','엉덩이를 들어 편다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 15),
  ('side-control', 'ezekiel-choke-from-side', '에제키엘 (사이드)', 'Ezekiel Choke from Side Control', array['사이드 에제키엘']::text[], array['한 팔을 상대 머리 아래로 넣는다','반대 손으로 그 소매 안쪽을 잡는다','손날을 상대 목 앞으로','가슴을 눌러 조인다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 16),
  ('side-control', 'north-south-choke-from-side', '남북 초크 (사이드에서)', 'North-South Choke from Side Control', array['남북 초크','노스사우스']::text[], array['팔을 상대 목 아래로 넣으며 남북로 돈다','어깨를 상대 목에 떨어뜨린다','손을 맞잡고 머리 쪽으로 더 내려간다','체중을 어깨로 실어 조인다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 17),
  ('side-control', 'breadcutter-choke', '브레드커터 초크', 'Breadcutter Choke', array['빵칼 초크']::text[], array['상대 먼 쪽 깃을 잡는다','팔뚝을 상대 목 앞에 가로로 댄다','무릎을 상대 머리 옆에 붙이고 체중을 싣는다','깃을 당기며 팔뚝으로 조인다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 18),
  ('side-control', 'loop-choke-from-side', '루프 초크 (사이드)', 'Loop Choke from Side Control', array['사이드 루프']::text[], array['상대 깃을 잡고 머리를 들게 만든다','깃 잡은 팔을 돌려 상대 목을 감는다','반대 팔을 상대 등 뒤로','몸을 돌리며 조인다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 19),
  ('side-control', 'von-flue-choke', '본 플루 초크', 'Von Flue Choke', array['길로틴 카운터 초크']::text[], array['상대가 사이드 아래에서 길로틴을 잡으면 반대쪽으로 다리를 넘긴다','어깨를 상대 목에 떨어뜨린다','손을 맞잡고 가슴을 낮춘다','체중으로 조인다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 20),
  ('side-control', 'triangle-choke-from-side', '트라이앵글 (사이드 위에서)', 'Triangle from Side Control', array['사이드 트라이앵글']::text[], array['상대 먼 팔을 당겨 가두고 가까운 다리를 상대 목 위로 넘긴다','반대 다리로 발목을 건다','상대 머리를 당긴다','조인다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 21),
