  ('mount', 'modified-mount', '모디파이드 마운트', 'Modified Mount', array['변형 마운트']::text[], array['상대가 옆으로 돌면 한 무릎은 등 뒤, 반대 무릎은 배 앞','상대 가까운 팔을 가둔다','체중을 낮춘다','초크 · 기무라']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 29),
  ('mount', 'cross-collar-choke-from-modified-mount', '크로스 칼라 초크 (모디파이드 마운트)', 'Cross Collar Choke from Modified Mount', array['변형 마운트 초크']::text[], array['옆으로 누운 상대 깃을 깊게 잡는다','반대 손 교차','몸을 낮춘다','조인다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph modified-mount/top (기 시도 13)', 30),
  ('mount', 'kimura-from-modified-mount', '기무라 (모디파이드 마운트)', 'Kimura from Modified Mount', array['변형 마운트 기무라']::text[], array['상대 윗팔 손목을 잡는다','반대 팔을 아래로 넣어 내 손목','팔꿈치를 붙인다','등 뒤로 돌린다']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph modified-mount/top (기 시도 10)', 31),
