  ('mount', 'elbow-escape-from-3-4-mount', '3/4 마운트 이스케이프', 'Elbow Escape from 3-4 Mount', array['쓰리쿼터 탈출']::text[], array['걸린 다리 쪽으로 엉덩이를 뺀다','팔꿈치로 상대 무릎을 민다','무릎을 넣어 하프','회복']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 3-4-mount/bottom (기 시도 11)', 34),
  ('mount', 'triangle-from-mount', '트라이앵글 (마운트에서)', 'Triangle from Mount', array['마운트 트라이앵글 진입']::text[], array['상대 한 팔을 밀어 올려 안쪽에 둔다','무릎을 상대 머리 옆으로 올린다','다리를 목 위로 넘긴다','마운티드 트라이앵글']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 3-4-mount/top (기 시도 7)', 35),
  ('mount', 'reverse-armbar-from-mount', '리버스 암바 (마운트)', 'Reverse Armbar from Mount', array['역 암바']::text[], array['상대가 내 가슴을 밀 때 그 팔을 겨드랑이에 끼운다','팔꿈치가 위로 가게 팔을 비튼다','몸을 낮추며 팔꿈치를 가슴으로 당긴다','탭']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph mount/top (기 시도 1)', 36),
  ('mount', 'trap-and-roll-from-high-mount', '트랩 앤 롤 (하이 마운트)', 'Trap and Roll from High Mount', array['하이 마운트 업파']::text[], array['상대 팔을 감싸 잡고 같은 쪽 발을 묶는다','엉덩이를 아래로 내리며 발을 세운다','브릿지로 넘긴다','가드 탑']::text[], false, 'AI 초안(우리 말로 작성) · 참고: BJJGraph high-mount/bottom (기 시도 10)', 37),
